export const getQuestionByGrade = (category: Category, grade: number, excludedIds: string[] = []): Question => {
  const allInCategory = QUESTIONS_DB.filter(q => q.category === category);
  let matchingQuestions = allInCategory.filter(q => q.minGrade <= grade && q.minGrade >= Math.max(2, grade - 2));
  if (matchingQuestions.filter(q => !excludedIds.includes(q.id)).length === 0) {
    matchingQuestions = allInCategory.filter(q => q.minGrade <= grade);
  }
  const finalPool = matchingQuestions.filter(q => !excludedIds.includes(q.id));
  if (finalPool.length === 0) {
    const backupPool = matchingQuestions.length > 0 ? matchingQuestions : allInCategory;
    return backupPool[Math.floor(Math.random() * backupPool.length)];
  }
  return finalPool[Math.floor(Math.random() * finalPool.length)];
};
